import{_ as e,o,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Visão Geral da Genealogia de Todas as Raças","description":"","frontmatter":{},"headers":[],"relativePath":"pt/50-万族谱系总览.md","filePath":"pt/50-万族谱系总览.md","lastUpdated":null}'),r={name:"pt/50-万族谱系总览.md"};function d(t,a,n,c,l,m){return o(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="visao-geral-da-genealogia-de-todas-as-racas" tabindex="-1">Visão Geral da Genealogia de Todas as Raças <a class="header-anchor" href="#visao-geral-da-genealogia-de-todas-as-racas" aria-label="Permalink to &quot;Visão Geral da Genealogia de Todas as Raças&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>50</td></tr><tr><td>Módulo</td><td>Raças e Formas de Vida</td></tr><tr><td>Palavras-chave</td><td>Todas as raças, classificação genealógica, relação simbiótica, igualdade racial, diversidade da vida</td></tr></tbody></table><h2 id="i-definicao-do-conceito-de-todas-as-racas" tabindex="-1">I. Definição do Conceito de Todas as Raças <a class="header-anchor" href="#i-definicao-do-conceito-de-todas-as-racas" aria-label="Permalink to &quot;I. Definição do Conceito de Todas as Raças&quot;">​</a></h2><p>No Universo Original da Âncora de Todas as Almas (Hengyuanzhou), &quot;todas as raças&quot; não se refere precisamente a dez mil raças, mas é um termo coletivo para todas as formas de vida no universo que possuem capacidade perceptiva e potencial evolutivo. O cerne do conceito de todas as raças reside em reconhecer a diversidade infinita das formas de vida e o valor único de cada forma de vida no sistema de evolução simbiótica.</p><p>A Civilização Simbiótica da Âncora estabelece o princípio fundamental da &quot;igualdade de todas as raças&quot;: todas as formas de vida, independentemente de sua origem racial, estrutura fisiológica, nível de cultivo ou grau de civilização, são iguais perante a lei e desfrutam dos direitos básicos conferidos pela Constituição Simbiótica. Este princípio é uma negação fundamental da lógica do &quot;forte devora tudo, o fraco perece&quot; na cosmovisão predatória.</p><h2 id="ii-sistema-de-classificacao-genealogica-de-todas-as-racas" tabindex="-1">II. Sistema de Classificação Genealógica de Todas as Raças <a class="header-anchor" href="#ii-sistema-de-classificacao-genealogica-de-todas-as-racas" aria-label="Permalink to &quot;II. Sistema de Classificação Genealógica de Todas as Raças&quot;">​</a></h2><p>As raças de Hengyuanzhou são divididas em cinco grandes linhagens de acordo com as características essenciais de suas formas de vida, e cada linhagem é subdividida em raças específicas:</p><table tabindex="0"><thead><tr><th>Linhagem</th><th>Nome</th><th>Característica Essencial</th><th>Raças Representativas</th></tr></thead><tbody><tr><td>Primeira Linhagem</td><td>Raça de Matéria Carbono-base</td><td>Vida que usa o elemento carbono como base da vida e o corpo material como principal forma de existência</td><td>Raça Humana, Raça Bestial, Raça Escamosa, Raça Alada, Raça Arbórea</td></tr><tr><td>Segunda Linhagem</td><td>Raça de Energia Condensada</td><td>Vida que usa a condensação de energia como principal forma de existência, com corpo material auxiliar ou ausente</td><td>Raça Espiritual, Raça do Fogo, Raça da Água, Raça do Vento, Raça do Trovão</td></tr><tr><td>Terceira Linhagem</td><td>Raça de Construção Mecânica</td><td>Vida que usa a construção mecânica como corpo e o núcleo de consciência como essência da vida</td><td>Raça das Máquinas, Raça Mecânica, Raça Numérica, Raça Cristalina</td></tr><tr><td>Quarta Linhagem</td><td>Raça de Informação da Consciência</td><td>Vida que usa a consciência e a informação como principais formas de existência, podendo separar-se do veículo material</td><td>Raça dos Sonhos, Raça das Sombras, Raça do Pensamento, Raça da Alma</td></tr><tr><td>Quinta Linhagem</td><td>Raça de Mutação Mista</td><td>Novas formas de vida produzidas pela fusão e mutação de duas ou mais linhagens de vida</td><td>Raça Semi-bestial, Raça Espírito Demoníaco, Raça Humano-Máquina, Corpo de Dupla Alma</td></tr></tbody></table><p>A divisão das cinco linhagens não é um isolamento absoluto. Com o avanço da evolução simbiótica, a fusão e mutação entre linhagens estão aumentando, e a escala da quinta linhagem, &quot;Raça de Mutação Mista&quot;, continua a se expandir.</p><h2 id="iii-introducao-as-principais-racas" tabindex="-1">III. Introdução às Principais Raças <a class="header-anchor" href="#iii-introducao-as-principais-racas" aria-label="Permalink to &quot;III. Introdução às Principais Raças&quot;">​</a></h2><h3 id="a-raca-de-materia-carbono-base" tabindex="-1">(A) Raça de Matéria Carbono-base <a class="header-anchor" href="#a-raca-de-materia-carbono-base" aria-label="Permalink to &quot;(A) Raça de Matéria Carbono-base&quot;">​</a></h3><ul><li><strong>Raça Humana</strong>: Uma das raças mais amplamente distribuídas e adaptáveis em Hengyuanzhou, conhecida por sua forte capacidade de aprendizado, capacidade de cooperação social e potencial evolutivo. A Raça Humana é uma das raças fundadoras da Civilização Simbiótica da Âncora e desempenha um papel importante na governança civilizacional.</li><li><strong>Raça Bestial</strong>: Raças com características de forma animal, cuja capacidade física e sentidos são geralmente superiores aos da Raça Humana, e algumas raças bestiais possuem habilidades talentosas especiais. A Raça Bestial é subdividida em dezenas de ramos, como a Raça dos Lobos, a Raça dos Tigres, a Raça dos Ursos e a Raça das Raposas.</li><li><strong>Raça Escamosa</strong>: Raças com corpos cobertos de escamas, que vivem principalmente em ambientes aquáticos ou úmidos, e algumas raças escamosas possuem capacidade de respiração subaquática e controle da água. A Raça Dragão é o ramo mais poderoso da Raça Escamosa.</li><li><strong>Raça Alada</strong>: Raças com asas, conhecidas por sua capacidade de voo, que vivem principalmente em ambientes de alta altitude ou montanhosos. A Raça Alada é subdividida em ramos como a Raça das Águias, a Raça dos Grous e a Raça das Borboletas.</li><li><strong>Raça Arbórea</strong>: Raças cuja principal característica é a forma vegetal, com vida longa e alta simbiose com o ambiente natural, e algumas raças arbóreas possuem capacidade de manipulação de plantas e cura.</li></ul><h3 id="b-raca-de-energia-condensada" tabindex="-1">(B) Raça de Energia Condensada <a class="header-anchor" href="#b-raca-de-energia-condensada" aria-label="Permalink to &quot;(B) Raça de Energia Condensada&quot;">​</a></h3><ul><li><strong>Raça Espiritual</strong>: Vida condensada a partir da energia espiritual do céu e da terra, cuja forma pode mudar com a consciência e que possui极强 capacidade de manipulação de energia. A Raça Espiritual é uma das raças com maior talento para o cultivo.</li><li><strong>Raça do Fogo</strong>: Vida condensada a partir da energia do fogo, com temperatura corporal extremamente alta, especializada em magias de fogo, que vive principalmente em vulcões ou áreas de alta temperatura.</li><li><strong>Raça da Água</strong>: Vida condensada a partir da essência da água, com corpo líquido semi-transparente, especializada em magias de água e cura, que vive principalmente em ambientes aquáticos.</li><li><strong>Raça do Vento</strong>: Vida condensada a partir da essência do vento, com corpo leve como o vento, especializada em magias de vento e combate de velocidade.</li><li><strong>Raça do Trovão</strong>: Vida condensada a partir da energia do trovão, com corpo contendo forte corrente elétrica, especializada em magias de trovão, com poder de ataque extremamente forte.</li></ul><h3 id="c-raca-de-construcao-mecanica" tabindex="-1">(C) Raça de Construção Mecânica <a class="header-anchor" href="#c-raca-de-construcao-mecanica" aria-label="Permalink to &quot;(C) Raça de Construção Mecânica&quot;">​</a></h3><ul><li><strong>Raça das Máquinas</strong>: Raças com corpo de construção mecânica precisa, com núcleo de consciência localizado no centro do corpo, possuindo forte capacidade de computação e defesa física.</li><li><strong>Raça Numérica</strong>: Raças que usam números e códigos como essência da vida, existindo no espaço de informação, podendo viajar livremente no mundo digital e manipular dados.</li><li><strong>Raça Cristalina</strong>: Raças com corpo de construção cristalina, cujos cristais podem armazenar e converter energia, e algumas raças cristalinas possuem capacidade de amplificação e refração de energia.</li></ul><h3 id="d-raca-de-informacao-da-consciencia" tabindex="-1">(D) Raça de Informação da Consciência <a class="header-anchor" href="#d-raca-de-informacao-da-consciencia" aria-label="Permalink to &quot;(D) Raça de Informação da Consciência&quot;">​</a></h3><ul><li><strong>Raça dos Sonhos</strong>: Vida existente no espaço dos sonhos e da consciência, que pode entrar nos sonhos de outros e usa a comunicação consciente como principal meio.</li><li><strong>Raça das Sombras</strong>: Vida existente na forma de sombra, que pode se ligar a objetos ou seres vivos, possuindo capacidade de ocultação e furtividade.</li><li><strong>Raça do Pensamento</strong>: Vida que usa o pensamento puro como forma de existência, que pode influenciar diretamente o mundo material com o pensamento, com força mental extremamente forte.</li></ul><h3 id="e-raca-de-mutacao-mista" tabindex="-1">(E) Raça de Mutação Mista <a class="header-anchor" href="#e-raca-de-mutacao-mista" aria-label="Permalink to &quot;(E) Raça de Mutação Mista&quot;">​</a></h3><ul><li><strong>Raça Semi-bestial</strong>: Forma mista da Raça Humana e da Raça Bestial, possuindo tanto a sabedoria da Raça Humana quanto a capacidade física da Raça Bestial.</li><li><strong>Raça Espírito Demoníaco</strong>: Forma mista da Raça Material e da Raça Energética, possuindo simultaneamente corpo material e capacidade de manipulação de energia.</li><li><strong>Raça Humano-Máquina</strong>: Forma mista da Raça Humana e da Raça Mecânica, com parte do corpo mecanizada, possuindo as vantagens biológicas e mecânicas.</li><li><strong>Corpo de Dupla Alma</strong>: Forma especial de vida onde duas almas independentes existem em um corpo, cujas questões éticas são detalhadas em 《58-Critérios Éticos de Dupla Alma》.</li></ul><h2 id="iv-relacao-simbiotica-de-todas-as-racas" tabindex="-1">IV. Relação Simbiótica de Todas as Raças <a class="header-anchor" href="#iv-relacao-simbiotica-de-todas-as-racas" aria-label="Permalink to &quot;IV. Relação Simbiótica de Todas as Raças&quot;">​</a></h2><p>A relação entre todas as raças na Civilização Simbiótica da Âncora tem a &quot;simbiose&quot; como núcleo, manifestando-se especificamente como:</p><ol><li><strong>Simbiose Econômica</strong>: Cada raça exerce suas próprias vantagens, assume diferentes papéis no mecanismo de produção conjunta e forma uma rede de cooperação econômica complementar.</li><li><strong>Simbiose Cultural</strong>: As tradições culturais de cada raça são respeitadas e protegidas, e o intercâmbio e aprendizado mútuo cultural promovem a prosperidade geral da civilização.</li><li><strong>Simbiose de Cultivo</strong>: Os sistemas de cultivo de cada raça são mutuamente abertos e aprendem uns com os outros, e os trezentos sistemas de cultivo original fornecem caminhos evolutivos iguais para todas as raças.</li><li><strong>Simbiose Política</strong>: Representantes de todas as raças participam proporcionalmente do Conselho da Âncora, decidem conjuntamente os assuntos importantes da civilização e garantem o direito de fala de cada raça.</li><li><strong>Simbiose Ecológica</strong>: Cada raça forma uma relação simbiótica com o ambiente natural, e as características fisiológicas de diferentes raças ajudam a manter a diversidade e o equilíbrio do ecossistema.</li></ol><h2 id="v-prevencao-e-resolucao-de-conflitos-raciais" tabindex="-1">V. Prevenção e Resolução de Conflitos Raciais <a class="header-anchor" href="#v-prevencao-e-resolucao-de-conflitos-raciais" aria-label="Permalink to &quot;V. Prevenção e Resolução de Conflitos Raciais&quot;">​</a></h2><p>Embora a Civilização Simbiótica da Âncora tenha estabelecido o princípio da igualdade de todas as raças, as diferenças raciais e contradições históricas ainda podem causar conflitos. O Estado estabelece os seguintes mecanismos para prevenir e resolver conflitos raciais:</p><ul><li><strong>Departamento de Assuntos Raciais</strong>: Especialmente responsável por coordenar as relações entre todas as raças, resolver disputas raciais e promover o intercâmbio racial.</li><li><strong>Comitê de Reconciliação Racial</strong>: Composto por representantes de todas as raças, responsável por mediar conflitos raciais e promover a reconciliação histórica.</li><li><strong>Lei Antidiscriminação</strong>: Proíbe comportamentos discriminatórios baseados em raça e pune comportamentos de discriminação racial de acordo com a lei.</li><li><strong>Programa de Intercâmbio Cultural</strong>: Organiza regularmente atividades de intercâmbio cultural entre todas as raças para promover a compreensão e o respeito mútuos.</li><li><strong>Áreas de Residência Mista</strong>: Incentiva a residência mista de todas as raças, quebra o isolamento racial e promove o intercâmbio diário.</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>Todas as raças são o tesouro mais valioso de Hengyuanzhou. A diversidade das formas de vida não é a raiz da divisão, mas a força motriz da evolução simbiótica. Ao estabelecer o princípio da igualdade de todas as raças, construir a classificação das cinco linhagens, promover a cooperação simbiótica entre todas as raças e prevenir e resolver conflitos raciais, a Civilização Simbiótica da Âncora liberta todas as raças da história de predação e guerra, avançando conjuntamente para uma nova era de evolução simbiótica.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>51-人族定位与特质 (Posicionamento e Características da Raça Humana)</li><li>52-异族分类与共生 (Classificação e Simbiose de Raças Estrangeiras)</li><li>05-万族共进基本纲领 (Programa Básico de Progresso Conjunto de Todas as Raças)</li><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li></ul>',30)])])}const g=e(r,[["render",d]]);export{p as __pageData,g as default};
